{"command": "cat > /testbed/test_fd0.c << 'EOF'
#include <stdio.h>
#include <sys/socket.h>
#include <sys/un.h>
#include <unistd.h>
#include <string.h>

// Simple test to verify that FD 0 can be used as a socket
int main() {
    int sv[2];

    // Create a socket pair
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, sv) < 0) {
        perror("socketpair");
        return 1;
    }

    // Close FD 0 (stdin) and dup one of the socket FDs to it
    close(0);
    if (dup(sv[0]) != 0) {
        perror("dup");
        return 1;
    }

    // Now FD 0 is a valid socket
    // Write to the other end
    const char *msg = "Hello, FD 0!";
    write(sv[1], msg, strlen(msg));

    // Read from FD 0
    char buf[64] = {0};
    ssize_t n = read(0, buf, sizeof(buf) - 1);

    if (n > 0) {
        printf("Successfully read from FD 0: %s\n", buf);
    }

    // Verify FD 0 is a valid socket using getsockname
    struct sockaddr_un addr;
    socklen_t len = sizeof(addr);
    if (getsockname(0, (struct sockaddr *)&addr, &len) == 0) {
        printf("FD 0 is a valid socket (family=%d)\n", addr.sun_family);
    } else {
        perror("getsockname");
        return 1;
    }

    close(0);
    close(sv[1]);

    printf("Test passed: FD 0 can be a valid socket\n");
    return 0;
}
EOF
